/**
 * Space Catalog V3 data model (ADR-034 P1, SRS §4.3).
 *
 * The catalog is read-only reference data generated by `tools/space-catalog/convert.ts`
 * from the user's V3 source. Projects never embed it: `dna.spaceCatalog` stores only stable
 * preset ids, and the registry resolves them at compile time.
 */
import { z } from "zod";

/** Version of the catalog data and its prompt wording; recorded in `PromptBundle.catalogVersion`. */
export const CATALOG_VERSION = "sc-3.0.0";

/**
 * Building archetypes in scope (ADR-034 amendment 2). Re-adding a type is a one-line change
 * here and in the converter allowlist, plus curation of its records.
 */
export const SPACE_ARCHETYPE_IDS = ["townhouse", "villa", "apartment", "hotel", "resort"] as const;
export type SpaceArchetypeId = (typeof SPACE_ARCHETYPE_IDS)[number];

export const SPACE_CATEGORIES = [
  "living",
  "kitchen_dining",
  "sleeping",
  "special",
  "outdoor",
  "service",
] as const;
export const SpaceCategorySchema = z.enum(SPACE_CATEGORIES);
export type SpaceCategory = z.infer<typeof SpaceCategorySchema>;

export const SPACE_ZONES = ["interior", "exterior", "semi_outdoor"] as const;
export const SpaceZoneSchema = z.enum(SPACE_ZONES);
export type SpaceZone = z.infer<typeof SpaceZoneSchema>;

/** `presetId` of a user-defined space ("Không gian khác / tùy chỉnh"); never in the catalog. */
export const CUSTOM_SPACE_PRESET_ID = "custom";

const id = z.string().trim().min(1);
const english = z.string().trim().min(1);

/** One required, optional or forbidden element; `id` is a stable slug of `en`. */
export const SpaceItemSchema = z.object({ id, en: english });
export type SpaceItem = z.infer<typeof SpaceItemSchema>;

export const SpaceVariantSchema = z.object({ id, labelVi: english, labelEn: english });
export type SpaceVariant = z.infer<typeof SpaceVariantSchema>;

export const BuildingArchetypeSchema = z.object({
  id,
  labelVi: english,
  labelEn: english,
});
export type BuildingArchetype = z.infer<typeof BuildingArchetypeSchema>;

export const SpacePresetSchema = z.object({
  id,
  buildingArchetypes: z.array(id).min(1),
  zone: SpaceZoneSchema,
  category: SpaceCategorySchema,
  labelVi: english,
  /** Real English, lower case as it reads inside a sentence ("compact rear courtyard"). */
  labelEn: english,
  availability: z.enum(["common", "optional"]),
  variants: z.array(SpaceVariantSchema).default([]),
  /** Stated as present only when the space's fact for the item is confirmed. */
  requiredIfVerified: z.array(SpaceItemSchema).default([]),
  /** Added only when the user approves them (`SpaceInstance.approvedOptionalIds`). */
  optional: z.array(SpaceItemSchema).default([]),
  /** Kept out unless the space's fact for the item is confirmed. */
  forbiddenUnlessConfirmed: z.array(SpaceItemSchema).default([]),
  /** The curated English scope prompt of the V3 record (reference text; not compiled verbatim). */
  scopeEn: english,
  source: id,
});
export type SpacePreset = z.infer<typeof SpacePresetSchema>;

export const SpaceCatalogFileSchema = z.object({
  catalogVersion: z.literal(CATALOG_VERSION),
  sourceVersion: id,
  archetypes: z.array(BuildingArchetypeSchema),
  presets: z.array(SpacePresetSchema),
});
export type SpaceCatalogFile = z.infer<typeof SpaceCatalogFileSchema>;
